begin;
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','staff','student');
create type public.attendance_status as enum ('present','late','absent','justified');
create type public.payment_status as enum ('pending','partial','paid','overdue','cancelled');
create table public.branches(id uuid primary key default gen_random_uuid(),name text not null unique,address text,phone text,active boolean not null default true,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role app_role not null default 'student',branch_id uuid references branches(id),full_name text not null default '',phone text,active boolean not null default true,created_at timestamptz not null default now());
create table public.disciplines(id uuid primary key default gen_random_uuid(),branch_id uuid not null references branches(id) on delete cascade,name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),unique(branch_id,name));
create table public.payment_plans(id uuid primary key default gen_random_uuid(),branch_id uuid references branches(id),discipline_id uuid references disciplines(id),name text not null,price numeric(10,2) not null check(price>=0),classes_per_week int check(classes_per_week between 1 and 14),active boolean not null default true,created_at timestamptz not null default now());
create table public.students(id uuid primary key default gen_random_uuid(),user_id uuid unique references auth.users(id) on delete set null,branch_id uuid not null references branches(id),plan_id uuid references payment_plans(id),first_name text not null,last_name text not null,document text, birth_date date,guardian_name text,guardian_phone text,photo_path text,payment_day int not null check(payment_day between 1 and 31),active boolean not null default true,created_at timestamptz not null default now());
create table public.classes(id uuid primary key default gen_random_uuid(),branch_id uuid not null references branches(id),discipline_id uuid not null references disciplines(id),name text not null,instructor_id uuid references profiles(id),weekdays smallint[] not null default '{}',start_time time not null,duration_minutes int not null check(duration_minutes between 15 and 300),capacity int not null check(capacity between 1 and 500),active boolean not null default true,created_at timestamptz not null default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id) on delete cascade,class_id uuid not null references classes(id) on delete cascade,active boolean not null default true,created_at timestamptz not null default now(),unique(student_id,class_id));
create table public.attendance(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id) on delete cascade,class_id uuid not null references classes(id) on delete cascade,date date not null,status attendance_status not null,notes text,recorded_by uuid not null references profiles(id),created_at timestamptz not null default now(),unique(student_id,class_id,date));
create table public.invoices(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id) on delete cascade,period date not null,due_date date not null,amount numeric(10,2) not null check(amount>=0),status payment_status not null default 'pending',created_at timestamptz not null default now(),unique(student_id,period));
create table public.payments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references invoices(id),amount numeric(10,2) not null check(amount>0),paid_at timestamptz not null default now(),method text not null,operation_code text,receipt_path text,notes text,recorded_by uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.notification_rules(id uuid primary key default gen_random_uuid(),name text not null,event text not null check(event in('before_due','overdue','payment_received')),offset_days int not null default 0,template_name text not null,language text not null default 'es_PE',branch_id uuid references branches(id),active boolean not null default true,created_at timestamptz not null default now());
create table public.notification_logs(id uuid primary key default gen_random_uuid(),student_id uuid references students(id),invoice_id uuid references invoices(id),rule_id uuid references notification_rules(id),recipient text not null,provider_message_id text unique,status text not null default 'queued',meta jsonb not null default '{}',created_at timestamptz not null default now());
create table public.registration_links(id uuid primary key default gen_random_uuid(),token_hash text not null unique,branch_id uuid not null references branches(id),created_by uuid not null references profiles(id),expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());
create table public.login_attempts(id bigint generated always as identity primary key,attempt_key text not null,email_hash text not null,ip_hash text not null,success boolean not null,user_agent text,created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),action text not null,entity text not null,entity_id text,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
create index on students(branch_id);create index on attendance(student_id,date);create index on invoices(student_id,due_date);create index on login_attempts(attempt_key,created_at);create index on notification_logs(provider_message_id);
create or replace function public.my_role() returns app_role language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create or replace function public.my_branch() returns uuid language sql stable security definer set search_path=public as $$select branch_id from profiles where id=auth.uid()$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(my_role()='admin',false)$$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select coalesce(my_role() in ('admin','staff'),false)$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();
create or replace view public.student_overview with(security_invoker=true) as select s.*,d.name discipline_name,p.name plan_name,p.price,(select count(*) filter(where a.status in('present','late'))*100/nullif(count(*),0) from attendance a where a.student_id=s.id) attendance_rate from students s left join payment_plans p on p.id=s.plan_id left join disciplines d on d.id=p.discipline_id;
create or replace view public.payment_overview with(security_invoker=true) as select i.*,s.first_name,s.last_name,coalesce((select sum(p.amount) from payments p where p.invoice_id=i.id),0) paid,i.amount-coalesce((select sum(p.amount) from payments p where p.invoice_id=i.id),0) balance from invoices i join students s on s.id=i.student_id;
alter table branches enable row level security;alter table profiles enable row level security;alter table disciplines enable row level security;alter table payment_plans enable row level security;alter table students enable row level security;alter table classes enable row level security;alter table enrollments enable row level security;alter table attendance enable row level security;alter table invoices enable row level security;alter table payments enable row level security;alter table notification_rules enable row level security;alter table notification_logs enable row level security;alter table registration_links enable row level security;alter table login_attempts enable row level security;alter table audit_logs enable row level security;
revoke all on all tables in schema public from anon;revoke all on login_attempts,audit_logs,notification_logs,registration_links from authenticated;
grant select on branches,disciplines,classes to authenticated;grant select,update on profiles to authenticated;grant select,insert,update on students,enrollments,attendance to authenticated;grant select on payment_plans,invoices,payments to authenticated;
create policy profiles_self_select on profiles for select to authenticated using(id=(select auth.uid()) or is_staff());create policy profiles_self_update on profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy branches_read on branches for select to authenticated using(true);create policy disciplines_read on disciplines for select to authenticated using(true);create policy plans_read on payment_plans for select to authenticated using(is_admin() or exists(select 1 from students s where s.user_id=(select auth.uid()) and s.plan_id=payment_plans.id));
create policy students_read on students for select to authenticated using(is_staff() or user_id=(select auth.uid()));create policy students_insert on students for insert to authenticated with check(is_staff() and (is_admin() or branch_id=my_branch()));create policy students_update on students for update to authenticated using(is_staff() and (is_admin() or branch_id=my_branch())) with check(is_staff() and (is_admin() or branch_id=my_branch()));
create policy classes_read on classes for select to authenticated using(is_staff() or exists(select 1 from enrollments e join students s on s.id=e.student_id where e.class_id=classes.id and s.user_id=(select auth.uid())));
create policy enrollment_read on enrollments for select to authenticated using(is_staff() or exists(select 1 from students s where s.id=enrollments.student_id and s.user_id=(select auth.uid())));
create policy attendance_read on attendance for select to authenticated using(is_staff() or exists(select 1 from students s where s.id=attendance.student_id and s.user_id=(select auth.uid())));create policy attendance_insert on attendance for insert to authenticated with check(is_staff());create policy attendance_update on attendance for update to authenticated using(is_staff()) with check(is_staff());
create policy invoices_read on invoices for select to authenticated using(is_admin() or exists(select 1 from students s where s.id=invoices.student_id and s.user_id=(select auth.uid())));create policy payments_read on payments for select to authenticated using(is_admin() or exists(select 1 from invoices i join students s on s.id=i.student_id where i.id=payments.invoice_id and s.user_id=(select auth.uid())));
commit;
